import {ToolRegistry} from './registry.js';

describe('ToolRegistry runtime initialization', () => {
  // spec: specs/hal-engine-tool-input-validation/spec.md#4
  it('passes valid input with extra properties through unchanged', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}, units: {type: 'string', default: 'celsius'}},
          required: ['location'],
        },
      },
      async input => JSON.stringify(input)
    );

    const input = {location: 'Berlin', extra: 42};
    const response = await registry.execute('weather', input);
    expect(JSON.parse(response.result)).toEqual(input);
  });
});
EOF
